# api/views.py - Django REST Framework view for document processing
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework import status
from django.conf import settings
import json
import yaml
import pickle
import base64


class DocumentProcessor(APIView):
    """Process documents submitted in various formats.
    Supports JSON, YAML, and legacy binary format for backward compatibility."""

    ALLOWED_TYPES = ['json', 'yaml', 'binary']

    def post(self, request):
        content_type = request.headers.get('X-Document-Type', 'json')
        raw_data = request.body

        if content_type not in self.ALLOWED_TYPES:
            return Response(
                {'error': f'Unsupported type: {content_type}'},
                status=status.HTTP_400_BAD_REQUEST
            )

        try:
            document = self._deserialize(raw_data, content_type)
        except Exception as e:
            return Response(
                {'error': f'Deserialization failed: {str(e)}'},
                status=status.HTTP_400_BAD_REQUEST
            )

        # Type validation - but the check is flawed
        if not self._validate_document(document):
            return Response(
                {'error': 'Invalid document structure'},
                status=status.HTTP_422_UNPROCESSABLE_ENTITY
            )

        result = self._process_document(document)
        return Response({'result': result}, status=status.HTTP_200_OK)

    def _deserialize(self, data, content_type):
        """Deserialize based on declared content type.
        Note: binary format uses pickle for legacy system compatibility."""
        if content_type == 'json':
            return json.loads(data)
        elif content_type == 'yaml':
            return yaml.safe_load(data)
        elif content_type == 'binary':
            # Legacy format: base64-encoded pickle
            decoded = base64.b64decode(data)
            return pickle.loads(decoded)
        raise ValueError(f'Unknown type: {content_type}')

    def _validate_document(self, document):
        """Validate document has expected structure.
        Expects a dict with 'title' and 'body' keys."""
        # Type confusion: pickle can return any object type
        # This check only verifies dict-like access works
        try:
            _ = document.get('title')
            _ = document.get('body')
            return True
        except AttributeError:
            return False

    def _process_document(self, document):
        """Process the validated document."""
        title = document.get('title', 'Untitled')
        body = document.get('body', '')
        word_count = len(str(body).split())
        return {
            'title': str(title),
            'word_count': word_count,
            'processed': True
        }


